return $input.all()
  .filter(i => i.json.lead_json)
  .map(i => {
    const lead = JSON.parse(i.json.lead_json);
    lead.hubspot_contact_id = i.json.hubspot_contact_id || lead.hubspot_contact_id || '';
    lead.hubspot_deal_id = i.json.hubspot_deal_id || lead.hubspot_deal_id || '';
    return { json: { op: 'rank', row: lead } };
  });

const fmt = v => v >= 1e6 ? (Math.round(v / 1e4) / 100) + 'M' : Math.round(v / 1e3) + 'K';
const budget = r => {
  if (r.budget_status !== 'known') return 'unknown';
  if (r.budget_min && r.budget_max && r.budget_min !== r.budget_max) return fmt(r.budget_min) + '-' + fmt(r.budget_max) + ' SAR';
  if (r.budget_max && !r.budget_min) return 'up to ' + fmt(r.budget_max) + ' SAR';
  return fmt(r.budget_min || r.budget_max) + ' SAR';
};
const assetAr = r => ((r.reason_ar || '').split(' | ')[(r.flags || {}).human_requested ? 2 : 1]) || '';
// Sales can take over: ready now (P1), asked for a person, or all core facts collected
const handoffReady = r => r.priority !== 'Disqualified' && (r.priority === 'P1' || Boolean((r.flags || {}).human_requested) || r.qualification_status === 'qualified');
const nextAction = r => {
  const f = r.flags || {};
  if (r.priority === 'Disqualified') return 'No action - ' + (r.disqualify_reason || 'disqualified');
  if (f.human_requested) return 'CALL NOW - customer asked for a person';
  if (r.qualification_status === 'needs_review') return 'Review conversation and clarify: ' + (r.uncertain_fields || []).join(', ');
  if (r.priority === 'P1') return 'CALL NOW - guide auction registration';
  if (f.contact_later) return 'Contact later as requested';
  if (r.priority === 'P2' && !['cash', 'financing_approved'].includes(r.financing)) return 'Follow up - resolve financing';
  if (r.priority === 'P2') return 'Follow up - complete: ' + ((r.missing_fields || []).join(', ') || 'confirm interest');
  return 'Nurture on WhatsApp - agent collecting: ' + ((r.missing_fields || []).join(', ') || '-');
};
return $input.all().map(i => i.json).map(r => ({ json: {
  rank: r.rank, priority: r.priority, score: r.score, handoff_ready: handoffReady(r) ? 'YES' : 'no', next_action: nextAction(r),
  name: r.name || '', mobile: r.mobile || '', email: r.email || '', city: r.city || '',
  interested_asset: assetAr(r), budget: budget(r), financial_readiness: r.financing, timeline: r.timeline,
  qualification_status: r.qualification_status, human_requested: (r.flags || {}).human_requested ? 'YES' : '',
  reason_ar: r.reason_ar, reason_en: r.reason_en, sources: (r.sources || []).join('+'),
  last_interaction_at: r.last_interaction_at, hubspot_contact_id: r.hubspot_contact_id, hubspot_deal_id: r.hubspot_deal_id
} }));
